package grading.submission;

import grading.assessment.AssessmentDefinition;
import grading.assessment.QuestionFiles;
import grading.common.FileTrees;
import grading.common.Messages;
import grading.config.GradingSettings;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;

/**
 * Validates and normalizes student submissions without changing their originals. Each submission
 * is opened, its owner resolved, its arrangement checked, and its required files copied into a
 * normalized copy laid out as the assessment expects.
 */
public final class SubmissionPreparationService {

    // Unmodified copies of the submitted sources, kept beside the normalized copies for style checks.
    private static final String ORIGINALS_FOLDER = ".originals";
    // Where each submission is opened before it is normalized; removed once it is done.
    private static final String STAGING_FOLDER = ".staging";
    private static final String MOVED = "Moved to where the assessment expects it.";

    private final ZipExtractor zipExtractor;
    private final UsernameResolver usernames = new UsernameResolver();
    private final SubmissionDiscovery discovery = new SubmissionDiscovery(usernames);
    private final StudentHeaders headers;
    private final List<SubmissionCheck> checks;
    private final long maxJavaFileBytes;

    /**
     * Uses the standard checks: the username folder, the question folders and extra Java files.
     *
     * @param settings the size limits and email domain used while preparing
     */
    public SubmissionPreparationService(GradingSettings settings) {
        this(settings, List.of(new UsernameFolderCheck(), new QuestionFolderCheck(), new ExtraJavaFilesCheck()));
    }

    /**
     * Uses the given checks of each submission's arrangement, in order.
     *
     * @param settings the size limits and email domain used while preparing
     * @param checks   the checks to run on each submission
     */
    public SubmissionPreparationService(GradingSettings settings, List<SubmissionCheck> checks) {
        this.zipExtractor = new ZipExtractor(settings.maxZipBytes(), settings.maxZipEntries());
        this.headers = new StudentHeaders(new IdentitySuggestions(settings.emailDomain()), settings.maxJavaFileBytes());
        this.checks = List.copyOf(checks);
        this.maxJavaFileBytes = settings.maxJavaFileBytes();
    }

    /**
     * Processes either a single ZIP/folder or a folder containing multiple submissions. An unexpected failure in one
     * submission is converted into a result and does not stop the remaining batch.
     *
     * @param input     a submission, or a folder of submissions
     * @param workspace the folder that receives the normalized copies
     * @return one result per submission found
     * @throws IOException if the input cannot be read at all
     */
    public List<SubmissionValidationResult> prepareBatch(Path input, Path workspace) throws IOException {
        return prepareBatch(input, workspace, ImportProgress.NONE);
    }

    /**
     * The same as {@link #prepareBatch(Path, Path)}, telling {@code progress} after each submission.
     *
     * @param input     a submission, or a folder of submissions
     * @param workspace the folder that receives the normalized copies
     * @param progress  told how many of the submissions found are done
     * @return one result per submission found
     * @throws IOException if the input cannot be read at all
     */
    public List<SubmissionValidationResult> prepareBatch(Path input, Path workspace, ImportProgress progress)
            throws IOException {
        requireReadableInput(input);
        Files.createDirectories(workspace);

        List<SubmissionValidationResult> results = new ArrayList<>();
        Set<String> outputNames = new HashSet<>();
        List<Path> found = discovery.discover(input, workspace);
        for (Path submission : found) {
            try {
                results.add(prepareOne(SubmissionSource.of(submission, zipExtractor), workspace, outputNames));
            } catch (Exception exception) {
                results.add(unreadable(submission, exception));
            }
            progress.prepared(results.size(), found.size(), submission.getFileName().toString());
        }
        return List.copyOf(results);
    }

    // The result for a submission that could not be prepared at all.
    private SubmissionValidationResult unreadable(Path submission, Exception exception) {
        String fallbackUsername = usernames.candidate(submission)
                .orElse(IdentitySuggestions.PLACEHOLDER_PREFIX + "submission");
        return new SubmissionValidationResult(submission, fallbackUsername, null, Map.of(),
                List.of(SubmissionFinding.error("SUBMISSION_UNREADABLE",
                        "Could not prepare this submission: " + Messages.describe(exception))));
    }

    private SubmissionValidationResult prepareOne(SubmissionSource source, Path workspace, Set<String> outputNames)
            throws IOException {
        List<SubmissionFinding> findings = new ArrayList<>();
        Path staging = Files.createDirectories(workspace.resolve(STAGING_FOLDER).resolve(UUID.randomUUID().toString()));
        try {
            Path content = source.open(staging, findings);
            List<Path> javaFiles = FileSearch.javaFiles(content);
            HeaderIdentity identity = headers.discover(javaFiles, findings);
            String username = usernames.resolve(source.path(), identity, findings);
            Normalization normalization = startNormalization(source, username,
                    outputName(username, outputNames, workspace, findings), workspace);

            SubmissionContext context = new SubmissionContext(source, content, username, javaFiles);
            for (SubmissionCheck check : checks) {
                check.inspect(context, findings);
            }
            Map<String, Path> sources = normalizeSources(context, identity, normalization, findings);
            Map<String, Path> dependencies = normalizeDependencies(content, normalization, findings);

            if (sources.isEmpty()) {
                // Nothing gradable: keep the findings but no normalized copy.
                FileTrees.delete(normalization.root());
                FileTrees.delete(normalization.originalsRoot());
                return new SubmissionValidationResult(source.path(), username, null, Map.of(), findings,
                        identity, normalization.corrections(), normalization.originals());
            }
            return new SubmissionValidationResult(source.path(), username, normalization.root(),
                    questionFiles(sources, dependencies), findings, identity, normalization.corrections(),
                    normalization.originals());
        } finally {
            deleteQuietly(staging);
        }
    }

    // The folder name of the normalized copy: the username, made unique when two submissions share it.
    private String outputName(String username, Set<String> outputNames, Path workspace,
            List<SubmissionFinding> findings) {
        String outputName = usernames.outputFolderName(username, outputNames, workspace);
        if (!outputName.equals(username)) {
            findings.add(SubmissionFinding.corrected("DUPLICATE_USERNAME",
                    "A duplicate username was found; normalized this copy as " + outputName + "."));
        }
        return outputName;
    }

    // Creates the normalized copy's folder and records the rename when it differs from what was submitted.
    private Normalization startNormalization(SubmissionSource source, String username, String outputName,
            Path workspace) throws IOException {
        Path root = workspace.resolve(outputName).normalize();
        ensureChildOf(workspace, root);
        Files.createDirectories(root);
        Normalization normalization = new Normalization(source, username, outputName, root,
                workspace.resolve(ORIGINALS_FOLDER).resolve(outputName));
        if (!usernames.candidate(source.path()).orElse("").equals(outputName)) {
            normalization.corrections().add(new FileCorrection(normalization.label(), outputName + "/",
                    "The normalized copy is named after the student's username."));
        }
        return normalization;
    }

    // The files each question needs, chosen from what was normalized.
    private static Map<String, QuestionFiles> questionFiles(Map<String, Path> sources,
            Map<String, Path> dependencies) {
        Map<String, QuestionFiles> questions = new LinkedHashMap<>();
        for (var question : AssessmentDefinition.QUESTIONS) {
            questions.put(question.id(), new QuestionFiles(
                    selectedFiles(question.sources(), sources),
                    selectedFiles(question.supportClasses(), dependencies),
                    selectedFiles(question.runtimeFiles(), dependencies)));
        }
        return questions;
    }

    // Normalizes every required source file; the map holds the ones that can be graded.
    private Map<String, Path> normalizeSources(SubmissionContext submission, HeaderIdentity identity,
            Normalization normalization, List<SubmissionFinding> findings) throws IOException {
        Map<String, Path> normalized = new LinkedHashMap<>();
        for (Map.Entry<String, String> requirement : AssessmentDefinition.sourceFiles().entrySet()) {
            Optional<Path> target = normalizeSource(submission, requirement.getValue(), requirement.getKey(),
                    identity, normalization, findings);
            if (target.isPresent()) {
                normalized.put(requirement.getKey(), target.get());
            }
        }
        return Map.copyOf(normalized);
    }

    // Copies one source file into its question folder, keeps an unmodified copy of it and checks its
    // header. Empty when the file is missing, unreadable or too large.
    private Optional<Path> normalizeSource(SubmissionContext submission, String folder, String fileName,
            HeaderIdentity identity, Normalization normalization, List<SubmissionFinding> findings)
            throws IOException {
        List<Path> candidates = FileSearch.filesNamed(submission.content(), fileName);
        if (candidates.isEmpty()) {
            findings.add(SubmissionFinding.error("MISSING_JAVA_FILE",
                    "Required file " + folder + "/" + fileName + " is missing."));
            return Optional.empty();
        }
        Path selected = preferred(candidates, folder);
        if (candidates.size() > 1) {
            findings.add(SubmissionFinding.warning("DUPLICATE_JAVA_FILE", "Found multiple copies of " + fileName
                    + "; used " + submission.content().relativize(selected) + "."));
        }

        Path target = Files.createDirectories(normalization.root().resolve(folder)).resolve(fileName);
        try {
            Files.copy(selected, target, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException exception) {
            findings.add(SubmissionFinding.error("JAVA_FILE_UNREADABLE",
                    "Could not copy " + fileName + ": " + Messages.describe(exception)));
            return Optional.empty();
        }

        String actualLocation = location(submission.content(), selected);
        if (!actualLocation.equals(normalization.expectedLocation(folder, fileName))) {
            findings.add(SubmissionFinding.corrected("JAVA_FILE_RELOCATED",
                    fileName + " was moved into " + folder + " in the normalized copy."));
            normalization.recordCorrection(actualLocation, folder, fileName, MOVED);
        }
        if (Files.size(target) > maxJavaFileBytes) {
            findings.add(SubmissionFinding.error("JAVA_FILE_TOO_LARGE",
                    fileName + " is too large to inspect or run safely; its question scores 0."));
            Files.delete(target);
            return Optional.empty();
        }
        normalization.keepOriginal(folder, target);
        repairHeader(submission, target, actualLocation, folder, identity, normalization, findings);
        return Optional.of(target);
    }

    // Adds a missing name or email to a normalized source's header, recording what was added.
    private void repairHeader(SubmissionContext submission, Path target, String actualLocation, String folder,
            HeaderIdentity identity, Normalization normalization, List<SubmissionFinding> findings) {
        String fileName = target.getFileName().toString();
        try {
            List<String> added = headers.checkAndRepair(target, submission.username(), identity, findings);
            if (!added.isEmpty()) {
                normalization.recordCorrection(actualLocation, folder, fileName,
                        "Added to the header: " + String.join("; ", added) + ".");
            }
        } catch (IOException exception) {
            findings.add(SubmissionFinding.error("HEADER_UNREADABLE",
                    "Could not inspect the header of " + fileName + ": " + Messages.describe(exception)));
        }
    }

    // Copies the support classes and test data the testers need from the student's submission.
    private Map<String, Path> normalizeDependencies(Path content, Normalization normalization,
            List<SubmissionFinding> findings) throws IOException {
        Map<String, String> requirements = new LinkedHashMap<>(AssessmentDefinition.supportClasses());
        requirements.putAll(AssessmentDefinition.runtimeFiles());
        Map<String, Path> normalized = new LinkedHashMap<>();
        for (var entry : requirements.entrySet()) {
            String fileName = entry.getKey();
            String folder = entry.getValue();
            List<Path> candidates = FileSearch.filesNamed(content, fileName);
            String relative = folder + "/" + fileName;
            if (candidates.isEmpty()) {
                findings.add(SubmissionFinding.error("MISSING_DEPENDENCY",
                        "Required grading dependency " + relative + " is missing."));
                continue;
            }
            Path selected = preferred(candidates, folder);
            if (candidates.size() > 1) {
                findings.add(SubmissionFinding.warning("DUPLICATE_DEPENDENCY", "Found multiple copies of " + fileName
                        + "; used " + content.relativize(selected) + "."));
            }
            try {
                Path copy = Files.copy(selected, Files.createDirectories(normalization.root().resolve(folder))
                        .resolve(fileName));
                normalized.put(fileName, copy);
                String actualLocation = location(content, selected);
                if (!actualLocation.equals(normalization.expectedLocation(folder, fileName))) {
                    normalization.recordCorrection(actualLocation, folder, fileName, MOVED);
                }
            } catch (IOException exception) {
                findings.add(SubmissionFinding.error("DEPENDENCY_UNREADABLE",
                        "Could not copy " + relative + ": " + Messages.describe(exception)));
            }
        }
        return normalized;
    }

    // The copy to use when a file was submitted more than once: the one in the expected folder first.
    private static Path preferred(List<Path> candidates, String folder) {
        candidates.sort(FileSearch.preferringFolder(folder));
        return candidates.getFirst();
    }

    // Where a file sits inside the submission, with forward slashes on every system.
    private static String location(Path content, Path file) {
        return content.relativize(file).toString().replace('\\', '/');
    }

    private static List<Path> selectedFiles(List<String> names, Map<String, Path> files) {
        return names.stream().filter(files::containsKey).map(files::get).toList();
    }

    private static void requireReadableInput(Path input) throws IOException {
        if (input == null || !Files.exists(input)) {
            throw new IOException("Submission path does not exist");
        }
        if (!Files.isReadable(input)) {
            throw new IOException("Submission path is not readable: " + input);
        }
        if (Files.isRegularFile(input) && !FileSearch.isZip(input)) {
            throw new IOException("Expected a submission folder or ZIP file: " + input);
        }
    }

    private static void ensureChildOf(Path parent, Path child) throws IOException {
        Path normalizedParent = parent.toAbsolutePath().normalize();
        Path normalizedChild = child.toAbsolutePath().normalize();
        if (!normalizedChild.startsWith(normalizedParent) || normalizedChild.equals(normalizedParent)) {
            throw new IOException("Refusing to write outside the normalization workspace");
        }
    }

    private static void deleteQuietly(Path folder) {
        try {
            FileTrees.delete(folder);
        } catch (IOException ignored) {
            // A cleanup problem must not turn a usable submission into a failed batch item.
        }
    }

    /** What normalizing one submission changed, and where its normalized and unmodified copies are kept. */
    private static final class Normalization {

        private final SubmissionSource source;
        private final String username;
        private final String outputName;
        private final Path root;
        private final Path originalsRoot;
        private final List<FileCorrection> corrections = new ArrayList<>();
        private final Map<String, Path> originals = new LinkedHashMap<>();

        private Normalization(SubmissionSource source, String username, String outputName, Path root,
                Path originalsRoot) {
            this.source = source;
            this.username = username;
            this.outputName = outputName;
            this.root = root;
            this.originalsRoot = originalsRoot;
        }

        /** The submission as the marker sees it: the ZIP or folder name. */
        String label() {
            return source.path().getFileName().toString();
        }

        /** The normalized copy's folder. */
        Path root() {
            return root;
        }

        Path originalsRoot() {
            return originalsRoot;
        }

        List<FileCorrection> corrections() {
            return corrections;
        }

        Map<String, Path> originals() {
            return originals;
        }

        String expectedLocation(String folder, String fileName) {
            return source.expectedLocation(username, folder, fileName);
        }

        // Records that a file found at actualLocation now sits in folder/fileName of the normalized copy.
        void recordCorrection(String actualLocation, String folder, String fileName, String reason) {
            corrections.add(new FileCorrection(label() + "/" + actualLocation,
                    outputName + "/" + folder + "/" + fileName, reason));
        }

        // Copies a source before its header is repaired, so style checks see what the student wrote.
        void keepOriginal(String folder, Path normalizedFile) throws IOException {
            Path copy = Files.createDirectories(originalsRoot.resolve(folder)).resolve(normalizedFile.getFileName());
            Files.copy(normalizedFile, copy, StandardCopyOption.REPLACE_EXISTING);
            originals.put(normalizedFile.getFileName().toString(), copy);
        }
    }
}
